using System;using UnityEngine;using UnityEditor;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckWifeCarrying.Editor {
public static class WifeCircuitPresentationAuthoring {
 public static void Install(WifeMatch match){if(GameObject.Find("Country circuit event spectators")!=null)return;var root=new GameObject("Country circuit event spectators").transform;var course=match.course;var data=course.terrain.terrainData;if(data.terrainLayers.Length!=2)throw new InvalidOperationException("Existing grass/mud terrain layers required");var paint=new float[data.alphamapHeight,data.alphamapWidth,2];var origin=course.terrain.transform.position;var extent=data.size;for(int z=0;z<paint.GetLength(0);z++)for(int x=0;x<paint.GetLength(1);x++){var point=new Vector3(origin.x+x/(float)(paint.GetLength(1)-1)*extent.x,0,origin.z+z/(float)(paint.GetLength(0)-1)*extent.z);float distance=course.Project(point,150,out float lateral);float route=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(14,23,Mathf.Abs(lateral)));float mud=distance>105&&distance<190?.8f:.32f+.1f*Mathf.Sin(distance*.12f);paint[z,x,1]=Mathf.Lerp(.02f,mud,route);paint[z,x,0]=1-paint[z,x,1];}data.SetAlphamaps(0,0,paint);EditorUtility.SetDirty(data);
 const string folder="Assets/TruckWifeCarrying/Models";System.IO.Directory.CreateDirectory(folder);AssetDatabase.Refresh();var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LWS/TruckTaxi/Prefabs/Pedestrians/Taxi_Girl_11.prefab"));try{int part=0;foreach(var skin in source.GetComponentsInChildren<SkinnedMeshRenderer>(true)){var mesh=new Mesh();skin.BakeMesh(mesh);string path=folder+"/Country spectator baked "+(part++)+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved==null){AssetDatabase.CreateAsset(mesh,path);saved=mesh;}else{EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}for(int i=0;i<24;i++){float s=20+i*11;float side=i%2==0?-27:27;var person=new GameObject("Installed country spectator "+i+" part "+part);person.transform.SetParent(root,false);person.transform.SetPositionAndRotation(course.Point(s,side),Quaternion.LookRotation(course.Point(s)-course.Point(s,side)));person.AddComponent<MeshFilter>().sharedMesh=saved;person.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;}}}finally{UnityEngine.Object.DestroyImmediate(source);}
 foreach(float s in new[]{8f,96f,205f}){var point=course.Point(s,-26);SportsRallyAuthoring.Prop(root,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock01_URP.prefab",point,new Vector3(4,1,.6f));var label=SportsEventAuthoring.Label("Country event banner","TRUCK SPORTS · COUNTRY CIRCUIT",point+Vector3.up*2.4f,.13f,new Color(1,.88f,.65f));label.gameObject.AddComponent<SportsPerCameraBillboard>();}EditorUtility.SetDirty(match);
 }
